mapper.select:
SELECT e.event_log_id::TEXT AS row_id, e.event_cd, c.name AS event_type_name, e.member_id, e.target_table, e.target_id, e.device_type, e.user_agent, e.reg_dt, e.reg_ip FROM event_log e LEFT JOIN code c ON c.code_id = e.event_cd AND c.p_code_id = 'EVENT00'
AND e.event_cd = #{eventCd}
ORDER BY e.event_log_id DESC LIMIT #{pageSize} OFFSET #{offset}
